<template>
  <div class="translation-control" :class="{ 'is-visible': visible, 'has-error': !!error }">
    <button
      type="button"
      class="translation-action"
      :disabled="loading"
      :aria-label="actionLabel"
      :aria-pressed="visible ? 'true' : 'false'"
      @click="$emit('toggle')"
      @pointerup="releaseFocus"
    >
      <span class="translation-globe" aria-hidden="true">
        <span v-if="loading" class="translation-spinner" />
        <svg v-else viewBox="0 0 20 20" fill="none">
          <circle cx="10" cy="10" r="7.25" />
          <path d="M2.9 10h14.2M10 2.75c2.05 2.08 3.08 4.5 3.08 7.25S12.05 15.17 10 17.25C7.95 15.17 6.92 12.75 6.92 10S7.95 4.83 10 2.75Z" />
        </svg>
      </span>
      <span class="translation-label">{{ visible ? 'Hide English translation' : 'Show English translation' }}</span>
      <span class="translation-state" aria-hidden="true" />
    </button>
    <p class="translation-status" :class="{ 'sr-only': !error }" aria-live="polite">{{ status }}</p>
  </div>
</template>

<script>
export default {
  name: 'ViewTranslationControl',
  props: {
    loading: { type: Boolean, default: false },
    visible: { type: Boolean, default: false },
    loaded: { type: Boolean, default: false },
    error: { type: String, default: '' },
  },
  emits: ['toggle'],
  computed: {
    actionLabel() {
      if (this.loading) return 'Preparing the English translation';
      return this.visible ? 'Hide the English translation' : 'Show the English translation';
    },
    status() {
      if (this.loading) return 'Preparing the English translation.';
      return this.error;
    },
  },
  methods: {
    releaseFocus(event) {
      if (event.pointerType !== 'keyboard') event.currentTarget.blur();
    },
  },
};
</script>

