<template>
  <div class="deck-embed">
    <div class="deck-frame" :class="{ 'touch-demo-gated': touchDemoEnabled, 'touch-demo-active': touchDemoActive }" ref="deckFrame">
      <iframe
        ref="deckIframe"
        src="https://www.henryw.me/CCGL9074/"
        title="Live scrollytelling deck built on the engine"
        loading="lazy"
        :tabindex="touchDemoEnabled && !touchDemoActive ? -1 : 0"
      ></iframe>
      <DemoInteractionGate
        v-if="touchDemoEnabled"
        :active="touchDemoActive"
        label="Explore this story"
        open-href="https://www.henryw.me/CCGL9074/"
        @activate="activateTouchDemo"
        @deactivate="deactivateTouchDemo"
      />
    </div>
    <FrameOpenLink class="deck-open-link" href="https://www.henryw.me/CCGL9074/" />
  </div>
</template>

<script>
import FrameOpenLink from './FrameOpenLink.vue';
import DemoInteractionGate from '../ui/DemoInteractionGate.vue';

export default {
  name: 'LiveDeckEmbed',
  components: { FrameOpenLink, DemoInteractionGate },
  data() {
    return { touchDemoEnabled: false, touchDemoActive: false };
  },
  mounted() {
    this._onDeckResize = () => this.scaleDeck();
    window.addEventListener('resize', this._onDeckResize);
    this.setupTouchDemo();
    this.$nextTick(() => this.scaleDeck());
  },
  unmounted() {
    if (this._onDeckResize) window.removeEventListener('resize', this._onDeckResize);
    if (this._touchDemoMedia && this._onTouchDemoMedia) {
      this._touchDemoMedia.removeEventListener?.('change', this._onTouchDemoMedia);
      this._touchDemoMedia.removeListener?.(this._onTouchDemoMedia);
    }
  },
  methods: {
    setupTouchDemo() {
      this._touchDemoMedia = window.matchMedia(
        '(max-width: 700px), (max-width: 1100px) and (hover: none) and (pointer: coarse)',
      );
      this._onTouchDemoMedia = (event) => {
        this.touchDemoEnabled = event.matches;
        if (!event.matches) this.touchDemoActive = false;
      };
      this._onTouchDemoMedia(this._touchDemoMedia);
      this._touchDemoMedia.addEventListener?.('change', this._onTouchDemoMedia);
      this._touchDemoMedia.addListener?.(this._onTouchDemoMedia);
    },
    activateTouchDemo() {
      this.touchDemoActive = true;
      this.$nextTick(() => this.$refs.deckIframe?.focus({ preventScroll: true }));
    },
    deactivateTouchDemo() { this.touchDemoActive = false; },
    scaleDeck() {
      const frame = this.$refs.deckFrame;
      const iframe = this.$refs.deckIframe;
      if (!frame || !iframe) return;
      const DESIGN_W = 1200;
      const DESIGN_H = 750;
      const cw = frame.clientWidth;
      const scale = cw / DESIGN_W;
      iframe.style.width = `${DESIGN_W}px`;
      iframe.style.height = `${DESIGN_H}px`;
      iframe.style.transform = `scale(${scale})`;
      frame.style.height = `${Math.round(DESIGN_H * scale)}px`;
    },
  },
};
</script>

<style scoped>
.deck-embed {
  --frame-open-line: rgba(255, 255, 255, 0.09);
  --frame-open-muted: #9a9a9a;
  --frame-open-ink: #e8e8e8;
  --frame-open-hover: rgba(255, 255, 255, 0.05);
  --frame-open-press: rgba(255, 255, 255, 0.09);
  margin: 1.2rem 0 0;
  border: 1px solid #e3e3ea;
  border-radius: 12px;
  overflow: hidden;
  background: #0e0e12;
}
.deck-frame {
  position: relative;
  width: 100%;
  overflow: hidden;
}
.deck-embed iframe {
  display: block;
  width: 100%;
  height: clamp(420px, 78vh, 760px);
  border: 0;
  transform-origin: top left;
}

body.dark-mode .deck-embed {
  border-color: #2e2e34;
}
@media (max-width: 700px) {
  .deck-open-link { display: none; }
  .deck-frame.touch-demo-gated iframe { pointer-events: none; }
  .deck-frame.touch-demo-active iframe { pointer-events: auto; }
}
@media (max-width: 1100px) and (hover: none) and (pointer: coarse) {
  .deck-open-link { display: none; }
  .deck-frame.touch-demo-gated iframe { pointer-events: none; }
  .deck-frame.touch-demo-active iframe { pointer-events: auto; }
}
</style>
